SELECT customer_first_name, customer_middle_initial, customer_last_name
FROM Customers
WHERE customer_id NOT IN (SELECT customer_id FROM Orders);

SELECT c.customer_first_name, c.customer_middle_initial, c.customer_last_name, cpm.payment_method_code
FROM Customers AS c
JOIN Customer_Payment_Methods AS cpm ON c.customer_id = cpm.customer_id;

SELECT c.customer_first_name, c.customer_middle_initial, c.customer_last_name, cpm.payment_method_code
FROM Customers AS c
JOIN Customer_Payment_Methods AS cpm ON c.customer_id = cpm.customer_id;

SELECT i.invoice_status_code, i.invoice_date, s.shipment_date
FROM Invoices AS i
JOIN Shipments AS s ON i.invoice_number = s.invoice_number;

SELECT i.invoice_status_code, i.invoice_date, s.shipment_date
FROM Invoices AS i
LEFT JOIN Shipments AS s ON i.invoice_number = s.invoice_number;

SELECT Type_of_Question_Code, COUNT(*) AS question_count
FROM Questions
GROUP BY Type_of_Question_Code;

SELECT Type_of_Question_Code, COUNT(*) AS occurrence_count
FROM Questions
GROUP BY Type_of_Question_Code;

SELECT Students.First_Name, Student_Answers.Date_of_Answer
FROM Students
JOIN Student_Answers ON Students.Student_ID = Student_Answers.Student_ID;

SELECT s.First_Name, sa.Date_of_Answer
FROM Student_Answers AS sa
JOIN Students AS s ON sa.Student_ID = s.Student_ID;

SELECT building.Address, region.Capital
FROM building
JOIN region ON building.Region_ID = region.Region_ID;

SELECT building.Address, region.Name
FROM building
JOIN region ON building.Region_ID = region.Region_ID;

SELECT s.bio_data, t.date_of_transcript
FROM Students AS s
JOIN Transcripts AS t ON s.student_id = t.student_id;

SELECT s.bio_data, t.date_of_transcript
FROM Students AS s
JOIN Transcripts AS t ON s.student_id = t.student_id;

SELECT s.bio_data, se.event_date
FROM Students AS s
JOIN Student_Events AS se ON s.student_id = se.student_id;

SELECT s.bio_data, se.event_date
FROM Students AS s
JOIN Student_Events AS se ON s.student_id = se.student_id;

SELECT COUNT(DISTINCT c.teacher_id)
FROM Classes AS c
WHERE c.student_id NOT IN (
    SELECT a.student_id
    FROM Achievements AS a
);

SELECT o.IdOrder, c.Name
FROM Orders AS o
JOIN Client AS c ON o.IdClient = c.IdClient;

SELECT DISTINCT Book.Title
FROM Book
JOIN Books_Order ON Book.ISBN = Books_Order.ISBN;

SELECT DISTINCT b.Title
FROM Book AS b
JOIN Books_Order AS bo ON b.ISBN = bo.ISBN;

SELECT DISTINCT c.Name
FROM Client AS c
JOIN Orders AS o ON c.IdClient = o.IdClient;

SELECT DISTINCT Client.Name
FROM Client
JOIN Orders ON Client.IdClient = Orders.IdClient;

SELECT customer.Name, customer_order.Dish_Name
FROM customer
JOIN customer_order ON customer.Customer_ID = customer_order.Customer_ID;

SELECT Document_Object_ID
FROM Document_Objects
WHERE Parent_Document_Object_ID IS NULL;

SELECT city1_code FROM Direct_distance WHERE distance > (SELECT AVG(distance) FROM Direct_distance)
UNION
SELECT city2_code FROM Direct_distance WHERE distance > (SELECT AVG(distance) FROM Direct_distance);

SELECT city1_code FROM Direct_distance WHERE distance < 1000
UNION
SELECT city2_code FROM Direct_distance WHERE distance < 1000;

SELECT title FROM Paintings WHERE painterID = 222
UNION
SELECT title FROM Sculptures WHERE sculptorID = 222;

SELECT p.property_name, a.county_state_province
FROM Properties AS p
JOIN Addresses AS a ON p.property_address_id = a.address_id;

SELECT DISTINCT u.age_category_code
FROM Users AS u
WHERE u.other_user_details LIKE '%Mother%';

SELECT first_name, middle_name, last_name, login_name
FROM Users
WHERE is_seller = 'Y';

SELECT "Date", COUNT(DISTINCT CustomerId) AS customer_count
FROM receipts
GROUP BY "Date";

SELECT driver.Driver, country.Country
FROM driver
JOIN country ON driver.Country = country.Country_Id;

SELECT Boxes.Code, Warehouses.Location
FROM Boxes
JOIN Warehouses ON Boxes.Warehouse = Warehouses.Code;

SELECT Home_Conference
FROM university
WHERE Enrollment > 2000;

SELECT document_id, document_name
FROM Documents
WHERE author_name = 'Bianka Cummings';

SELECT process_outcome_description
FROM Process_Outcomes
WHERE process_outcome_code = 'working';

SELECT staff_role_code, COUNT(*) AS process_count
FROM Staff_in_Processes
GROUP BY staff_role_code;

SELECT DISTINCT a.agency_id, a.agency_details
FROM Agencies AS a
JOIN Clients AS c ON a.agency_id = c.agency_id;

SELECT DISTINCT a.agency_id, a.agency_details
FROM Agencies AS a
JOIN Clients AS c ON a.agency_id = c.agency_id;

SELECT invoice_status, COUNT(*) AS invoice_count
FROM Invoices
GROUP BY invoice_status;

SELECT DISTINCT i.invoice_id, i.invoice_status
FROM Invoices AS i
JOIN Payments AS p ON p.invoice_id = i.invoice_id;

SELECT client_id, COUNT(meeting_id) AS meeting_count
FROM Meetings
GROUP BY client_id;

SELECT m.meeting_id, m.meeting_outcome, m.meeting_type, c.client_details
FROM Meetings AS m
JOIN Clients AS c ON m.client_id = c.client_id;
